/* 탄자니아 탭(P8) = info pages, no words/audio (src/info_tz.py, info_patch.py) */const TZINFO={"part":{"id":"P8","ko":"탄자니아","desc":"탄자니아를 이해하기 위한 자료","subs":[{"id":"P8-A","name":"나라 한눈에","b":["8-01-01","8-01-02","8-01-03","8-01-04"]},{"id":"P8-B","name":"땅과 지역","b":["8-02-01","8-02-02","8-02-03","8-02-04"]},{"id":"P8-C","name":"역사","b":["8-03-01","8-03-02","8-03-03"]},{"id":"P8-D","name":"종교와 믿음","b":["8-04-01","8-04-02","8-04-03"]},{"id":"P8-E","name":"명절과 기념일","b":["8-05-01","8-05-02","8-05-03","8-05-04"]},{"id":"P8-F","name":"음식 문화","b":["8-06-01","8-06-02","8-06-03","8-06-04"]},{"id":"P8-G","name":"생활과 예절","b":["8-07-01","8-07-02","8-07-03","8-07-04"]},{"id":"P8-H","name":"문화와 예술","b":["8-08-01","8-08-02","8-08-03","8-08-04"]},{"id":"P8-I","name":"가 볼 만한 곳","b":["8-09-01","8-09-02","8-09-03","8-09-04","8-09-05"]}]},"B":{"8-01-01":{"t":"나라 이름과 국기","h":"Jina la nchi na bendera","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>나라 이름과 국기</h2><div class=\"sub2 lo\">Jina la nchi na bendera</div><div class=\"top2\"><div><figure><svg class=\"flag\" viewBox=\"0 0 300 200\" role=\"img\" aria-label=\"탄자니아 국기\"><rect width=\"300\" height=\"200\" fill=\"#00A3DD\"/><polygon points=\"0,0 300,0 0,200\" fill=\"#1EB53A\"/><polygon points=\"0,200 0,150 225,0 300,0 300,50 75,200\" fill=\"#FCD116\"/><polygon points=\"0,200 0,168 252,0 300,0 300,32 48,200\" fill=\"#000\"/></svg><figcaption>탄자니아 국기 <span class=\"lo\">bendera ya Tanzania</span> <span class=\"r\">벤데라 야 탄자니아</span> (1964년부터)</figcaption></figure></div><div><table class=\"facts\"><tr><th>정식 이름</th><td>탄자니아 연합 공화국<br><span class=\"lo\">Jamhuri ya Muungano wa Tanzania</span> <span class=\"r\">잠후리 야 무웅가노 와 탄자니아</span></td></tr><tr><th>수도</th><td>도도마 <span class=\"lo\">Dodoma</span> <span class=\"r\">도도마</span> (가장 큰 도시는 다르에스살람)</td></tr><tr><th>독립</th><td>탕가니카 1961년 12월 9일<br>잔지바르와 합쳐 1964년 4월 26일</td></tr><tr><th>국가(노래)</th><td><span class=\"lo\">Mungu Ibariki Afrika</span> <span class=\"r\">뭉구 이바리키 아프리카</span> (하나님, 아프리카를 축복하소서)</td></tr><tr><th>표어</th><td><span class=\"lo\">Uhuru na Umoja</span> <span class=\"r\">우후루 나 우모자</span> (자유와 단결)</td></tr><tr><th>시간</th><td>한국보다 6시간 늦어요 (UTC+3)</td></tr><tr><th>전화·인터넷</th><td>+255 · .tz</td></tr></table></div></div><div class=\"two\"><div><h3>국기의 색과 뜻</h3><div class=\"clr\"><div><i style=\"background:#1EB53A\"></i><span><b>초록</b>: 땅과 자연</span></div><div><i style=\"background:#FCD116\"></i><span><b>노랑</b>: 땅속 자원(광물)</span></div><div><i style=\"background:#000\"></i><span><b>검정</b>: 사람들</span></div><div><i style=\"background:#00A3DD\"></i><span><b>파랑</b>: 바다와 호수</span></div></div><p>탕가니카 국기(초록·검정·노랑)와 잔지바르 국기(파랑·검정·초록)를 합쳐서 만들었어요. 대각선 띠가 두 나라가 하나 됨을 보여 줘요.</p></div><div><h3>나라 이름의 뜻</h3><p>본토 이름 <b>탕가니카</b>와 섬 이름 <b>잔지바르</b>의 앞 글자를 합쳐 <b>Tan-Zan-ia</b>가 되었어요.</p><div class=\"terms\"><div><span class=\"lo\">Tanganyika</span> <span class=\"r\">탕가니카</span><span class=\"m\">탕가니카 (본토)</span></div><div><span class=\"lo\">Zanzibar</span> <span class=\"r\">잔지바르</span><span class=\"m\">잔지바르 (섬)</span></div><div><span class=\"lo\">Muungano</span> <span class=\"r\">무웅가노</span><span class=\"m\">연합, 하나로 합침</span></div><div><span class=\"lo\">Jamhuri</span> <span class=\"r\">잠후리</span><span class=\"m\">공화국</span></div></div></div></div>"},"8-01-02":{"t":"수도와 인구","h":"Mji mkuu na wakazi","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>수도와 인구</h2><div class=\"sub2 lo\">Mji mkuu na wakazi</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/dodoma.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>도도마 시내 거리<small>사진: Mangapwani · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>수도</th><td>도도마 (나라 한가운데)</td></tr><tr><th>가장 큰 도시</th><td>다르에스살람 (항구, 경제 중심)</td></tr><tr><th>나라 인구</th><td>약 6,200만 명 (2022년 조사)</td></tr><tr><th>넓이</th><td>약 94만 7천 ㎢ (남한의 9배쯤)</td></tr><tr><th>바다</th><td>인도양</td></tr><tr><th>이웃 나라</th><td>케냐, 우간다, 르완다, 부룬디, 콩고민주공화국, 잠비아, 말라위, 모잠비크</td></tr></table></div></div><div class=\"two\"><div><h3>두 도시</h3><p>1973년에 수도를 나라 한가운데 있는 도도마로 옮기기로 했고, 정부 기관이 차츰 옮겨 갔어요.</p><p>다르에스살람은 지금도 가장 큰 도시이자 항구예요. 대사관과 회사가 많아요. 줄여서 <b>Dar</b>나 <b>Bongo</b>라고도 해요.</p></div><div><h3>사람들</h3><p>젊은 나라예요. 국민의 절반 가까이가 열여덟 살 아래예요.</p><p>120개가 넘는 민족이 함께 살아요. 그래도 스와힐리어가 모두를 이어 주는 말이라, 민족이 달라도 서로 말이 통해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mji mkuu</span> <span class=\"r\">음지 음쿠우</span><span class=\"m\">수도</span></div><div><span class=\"lo\">mji</span> <span class=\"r\">음지</span><span class=\"m\">도시</span></div><div><span class=\"lo\">kijiji</span> <span class=\"r\">키지지</span><span class=\"m\">마을</span></div><div><span class=\"lo\">wakazi</span> <span class=\"r\">와카지</span><span class=\"m\">주민</span></div><div><span class=\"lo\">Mtanzania</span> <span class=\"r\">음탄자니아</span><span class=\"m\">탄자니아 사람</span></div></div>"},"8-01-03":{"t":"정부와 행정","h":"Serikali","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>정부와 행정</h2><div class=\"sub2 lo\">Serikali</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>나라 형태</th><td>연합 공화국 (대통령제)</td></tr><tr><th>나라 대표</th><td>대통령 <span class=\"lo\">Rais</span> <span class=\"r\">라이스</span></td></tr><tr><th>국회</th><td><span class=\"lo\">Bunge</span> <span class=\"r\">붕게</span> (도도마)</td></tr><tr><th>잔지바르</th><td>따로 대통령과 의회가 있는 자치 지역</td></tr><tr><th>행정 구역</th><td>31개 주 <span class=\"lo\">mkoa</span> <span class=\"r\">음코아</span></td></tr><tr><th>국제 모임</th><td>동아프리카공동체(EAC), 남아프리카개발공동체(SADC)</td></tr></table></div></div><div class=\"two\"><div><h3>행정 단위</h3><p>나라는 주, 군, 면, 마을 순서로 나뉘어요.</p><div class=\"terms\"><div><span class=\"lo\">mkoa</span> <span class=\"r\">음코아</span><span class=\"m\">주 (31곳)</span></div><div><span class=\"lo\">wilaya</span> <span class=\"r\">윌라야</span><span class=\"m\">군</span></div><div><span class=\"lo\">kata</span> <span class=\"r\">카타</span><span class=\"m\">면</span></div><div><span class=\"lo\">kijiji</span> <span class=\"r\">키지지</span><span class=\"m\">마을</span></div><div><span class=\"lo\">mtaa</span> <span class=\"r\">음타아</span><span class=\"m\">동네 (도시)</span></div></div></div><div><h3>잔지바르</h3><p>잔지바르는 탄자니아의 일부지만 스스로 다스리는 부분이 많아요. 본토에서 잔지바르로 갈 때도 여권을 보여 주는 경우가 있어요.</p></div></div>"},"8-01-04":{"t":"말과 돈","h":"Lugha na fedha","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>말과 돈</h2><div class=\"sub2 lo\">Lugha na fedha</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/shilingi.jpg\" width=\"800\" height=\"393\" loading=\"lazy\" alt=\"\"><figcaption>1만 실링 지폐 (코끼리)<small>사진: Plouf250 · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>나라말</th><td>스와힐리어 <span class=\"lo\">Kiswahili</span> <span class=\"r\">키스와힐리</span></td></tr><tr><th>또 쓰는 말</th><td>영어 (법원, 대학, 무역)</td></tr><tr><th>학교 수업</th><td>초등학교는 스와힐리어, 중학교부터 주로 영어</td></tr><tr><th>돈</th><td>탄자니아 실링 <span class=\"lo\">shilingi</span> <span class=\"r\">쉴링기</span> (TZS)</td></tr><tr><th>지폐</th><td>500, 1,000, 2,000, 5,000, 10,000실링</td></tr><tr><th>휴대폰 결제</th><td>엠페사 <span class=\"lo\">M-Pesa</span> <span class=\"r\">엠페사</span> 등</td></tr></table></div></div><div class=\"two\"><div><h3>말</h3><p>초대 대통령 니에레레가 스와힐리어를 나라말로 키웠어요. 그래서 탄자니아는 아프리카에서 가장 많은 사람이 같은 아프리카 말을 쓰는 나라예요.</p><p>집에서는 자기 민족 말(수쿠마어, 차가어 등)을 쓰고, 밖에서는 스와힐리어를 쓰는 사람이 많아요.</p></div><div><h3>돈</h3><p>값은 흔히 천 단위로 말해요. <span class=\"lo\">elfu moja</span> <span class=\"r\">엘푸 모자</span>는 천, <span class=\"lo\">elfu kumi</span> <span class=\"r\">엘푸 쿠미</span>는 만 실링이에요.</p><p>시장, 바자지, 작은 가게는 현금이나 휴대폰 송금으로 내요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">Kiswahili</span> <span class=\"r\">키스와힐리</span><span class=\"m\">스와힐리어</span></div><div><span class=\"lo\">Kiingereza</span> <span class=\"r\">키잉게레자</span><span class=\"m\">영어</span></div><div><span class=\"lo\">lugha</span> <span class=\"r\">루가</span><span class=\"m\">언어</span></div><div><span class=\"lo\">pesa</span> <span class=\"r\">페사</span><span class=\"m\">돈</span></div><div><span class=\"lo\">shilingi</span> <span class=\"r\">쉴링기</span><span class=\"m\">실링</span></div></div>"},"8-02-01":{"t":"산과 호수","h":"Milima na maziwa","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>산과 호수</h2><div class=\"sub2 lo\">Milima na maziwa</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>가장 높은 산</th><td>킬리만자로 <span class=\"lo\">Kilimanjaro</span> <span class=\"r\">킬리만자로</span> (5,895m, 아프리카 최고봉)</td></tr><tr><th>큰 호수</th><td>빅토리아 호수, 탕가니카 호수, 냐사(말라위) 호수</td></tr><tr><th>큰 강</th><td>루피지 강</td></tr><tr><th>계곡</th><td>동아프리카 대지구대</td></tr><tr><th>바다</th><td>인도양 해안 약 1,400km</td></tr></table></div></div><div class=\"two\"><div><h3>지붕에 눈이 있는 산</h3><p>킬리만자로는 적도 근처인데도 꼭대기에 눈과 얼음이 있어요. 가장 높은 봉우리 이름은 <span class=\"lo\">Uhuru</span> <span class=\"r\">우후루</span>(자유)예요.</p><p>산기슭 모시와 아루샤 근처는 서늘하고 비가 많아 커피와 바나나를 길러요.</p></div><div><h3>세 개의 큰 호수</h3><p>빅토리아 호수는 아프리카에서 가장 큰 호수로, 나일강이 시작되는 곳이에요. 탕가니카 호수는 세계에서 두 번째로 깊어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mlima</span> <span class=\"r\">음리마</span><span class=\"m\">산</span></div><div><span class=\"lo\">ziwa</span> <span class=\"r\">지와</span><span class=\"m\">호수</span></div><div><span class=\"lo\">mto</span> <span class=\"r\">음토</span><span class=\"m\">강</span></div><div><span class=\"lo\">bahari</span> <span class=\"r\">바하리</span><span class=\"m\">바다</span></div><div><span class=\"lo\">bonde</span> <span class=\"r\">본데</span><span class=\"m\">골짜기</span></div></div>"},"8-02-02":{"t":"날씨와 계절","h":"Hali ya hewa","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>날씨와 계절</h2><div class=\"sub2 lo\">Hali ya hewa</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/rain.jpg\" width=\"800\" height=\"450\" loading=\"lazy\" alt=\"\"><figcaption>세렝게티에 몰려오는 비구름<small>사진: Christoph Strässler · CC BY-SA 2.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>기후</th><td>해안은 덥고 습함, 고원은 서늘함</td></tr><tr><th>큰비</th><td>3~5월 <span class=\"lo\">masika</span> <span class=\"r\">마시카</span></td></tr><tr><th>작은 비</th><td>11~12월 <span class=\"lo\">vuli</span> <span class=\"r\">불리</span></td></tr><tr><th>건기</th><td>6~10월 (서늘하고 맑음)</td></tr><tr><th>더운 때</th><td>12~2월</td></tr></table></div></div><div class=\"two\"><div><h3>비로 나누는 계절</h3><p>적도 가까이라 사계절보다 비 오는 때와 마른 때로 계절을 나눠요. 큰비가 오는 3~5월에는 길이 진흙탕이 되기도 해요.</p><p>6~10월 건기는 맑고 선선해서 사파리 여행을 많이 가요.</p></div><div><h3>높이에 따라 달라요</h3><p>같은 날에도 다르에스살람은 30도가 넘고, 음베야나 이링가 같은 고원은 겉옷이 필요할 만큼 서늘해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mvua</span> <span class=\"r\">음부아</span><span class=\"m\">비</span></div><div><span class=\"lo\">jua</span> <span class=\"r\">주아</span><span class=\"m\">해, 햇볕</span></div><div><span class=\"lo\">joto</span> <span class=\"r\">조토</span><span class=\"m\">더위</span></div><div><span class=\"lo\">baridi</span> <span class=\"r\">바리디</span><span class=\"m\">추위</span></div><div><span class=\"lo\">kiangazi</span> <span class=\"r\">키앙가지</span><span class=\"m\">건기</span></div></div>"},"8-02-03":{"t":"본토와 섬","h":"Bara na Visiwani","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>본토와 섬</h2><div class=\"sub2 lo\">Bara na Visiwani</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/coast.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>잔지바르 마템웨 해변<small>사진: Olivier Lejade from France · CC BY-SA 2.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>본토</th><td><span class=\"lo\">Tanzania Bara</span> <span class=\"r\">탄자니아 바라</span> (옛 탕가니카)</td></tr><tr><th>잔지바르 제도</th><td><span class=\"lo\">Unguja</span> <span class=\"r\">웅구자</span>(큰 섬)와 <span class=\"lo\">Pemba</span> <span class=\"r\">펨바</span></td></tr><tr><th>그 밖의 섬</th><td>마피아 섬 등</td></tr><tr><th>해안 도시</th><td>다르에스살람, 탕가, 음트와라, 바가모요</td></tr><tr><th>내륙 도시</th><td>도도마, 아루샤, 므완자, 음베야</td></tr></table></div></div><div class=\"two\"><div><h3>해안과 섬</h3><p>해안과 잔지바르는 옛날부터 아랍, 페르시아, 인도와 바다로 오가며 장사했어요. 스와힐리 문화가 생겨난 곳이에요.</p><p>잔지바르 사람들은 본토를 <span class=\"lo\">Bara</span> <span class=\"r\">바라</span>, 섬을 <span class=\"lo\">Visiwani</span> <span class=\"r\">비시와니</span>라고 불러요.</p></div><div><h3>여러 지역</h3><p>북쪽은 산과 국립공원, 서쪽은 큰 호수, 남쪽은 고원과 차밭, 가운데는 마른 초원이 많아요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">kisiwa</span> <span class=\"r\">키시와</span><span class=\"m\">섬 (여럿은 visiwa)</span></div><div><span class=\"lo\">pwani</span> <span class=\"r\">프와니</span><span class=\"m\">해안</span></div><div><span class=\"lo\">bara</span> <span class=\"r\">바라</span><span class=\"m\">본토, 내륙</span></div><div><span class=\"lo\">kaskazini</span> <span class=\"r\">카스카지니</span><span class=\"m\">북쪽</span></div><div><span class=\"lo\">kusini</span> <span class=\"r\">쿠시니</span><span class=\"m\">남쪽</span></div></div>"},"8-02-04":{"t":"동물과 자연","h":"Wanyamapori","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>동물과 자연</h2><div class=\"sub2 lo\">Wanyamapori</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/serengeti.jpg\" width=\"800\" height=\"533\" loading=\"lazy\" alt=\"\"><figcaption>마라 강을 건너는 누 떼<small>사진: Agness Abubakar Saidi · CC0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>국립공원</th><td>20개가 넘어요</td></tr><tr><th>보호 지역</th><td>나라 땅의 약 3분의 1</td></tr><tr><th>유명한 동물</th><td>사자, 코끼리, 기린, 누, 얼룩말, 하마</td></tr><tr><th>국가 동물</th><td>기린 <span class=\"lo\">twiga</span> <span class=\"r\">트위가</span></td></tr><tr><th>바다</th><td>산호초, 돌고래, 바다거북</td></tr></table></div></div><div class=\"two\"><div><h3>큰 이동</h3><p>해마다 누와 얼룩말 수백만 마리가 풀을 따라 세렝게티와 케냐 마사이마라 사이를 돌아요. 이것을 대이동이라고 해요.</p></div><div><h3>기린이 나라 동물</h3><p>기린은 탄자니아를 나타내는 동물이에요. 나라 문장에도, 국립공원 표지에도 자주 나와요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mnyama</span> <span class=\"r\">음냐마</span><span class=\"m\">동물</span></div><div><span class=\"lo\">simba</span> <span class=\"r\">심바</span><span class=\"m\">사자</span></div><div><span class=\"lo\">tembo</span> <span class=\"r\">템보</span><span class=\"m\">코끼리</span></div><div><span class=\"lo\">twiga</span> <span class=\"r\">트위가</span><span class=\"m\">기린</span></div><div><span class=\"lo\">pundamilia</span> <span class=\"r\">푼다밀리아</span><span class=\"m\">얼룩말</span></div></div>"},"8-03-01":{"t":"스와힐리 해안의 옛날","h":"Historia ya pwani","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>스와힐리 해안의 옛날</h2><div class=\"sub2 lo\">Historia ya pwani</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/kilwa.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>킬와 키시와니의 후수니 쿠브와 유적<small>사진: Mateo.Mfalme · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>옛 무역</th><td>인도양 계절풍을 타고 아랍·페르시아·인도와 거래</td></tr><tr><th>옛 도시</th><td>킬와, 바가모요, 잔지바르</td></tr><tr><th>스와힐리어</th><td>반투어에 아랍어 낱말이 많이 들어옴</td></tr><tr><th>세계유산</th><td>킬와 키시와니 유적 (1981년)</td></tr></table></div></div><div class=\"two\"><div><h3>바닷길 무역</h3><p>천 년도 더 전부터 해안 도시들은 금, 상아, 향신료를 배로 실어 나르며 장사했어요. 이때 스와힐리어와 스와힐리 문화가 자랐어요.</p></div><div><h3>말 속의 흔적</h3><p>그래서 스와힐리어에는 아랍어에서 온 낱말이 많아요. <span class=\"lo\">kitabu</span> <span class=\"r\">키타부</span>(책), <span class=\"lo\">saa</span> <span class=\"r\">사아</span>(시계), <span class=\"lo\">dunia</span> <span class=\"r\">두니아</span>(세상)도 그래요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">historia</span> <span class=\"r\">히스토리아</span><span class=\"m\">역사</span></div><div><span class=\"lo\">biashara</span> <span class=\"r\">비아샤라</span><span class=\"m\">장사, 무역</span></div><div><span class=\"lo\">pwani</span> <span class=\"r\">프와니</span><span class=\"m\">해안</span></div><div><span class=\"lo\">jahazi</span> <span class=\"r\">자하지</span><span class=\"m\">돛단배 (다우)</span></div><div><span class=\"lo\">zamani</span> <span class=\"r\">자마니</span><span class=\"m\">옛날</span></div></div>"},"8-03-02":{"t":"식민지 시대","h":"Ukoloni","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>식민지 시대</h2><div class=\"sub2 lo\">Ukoloni</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/bagamoyo.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>바가모요 옛 건물의 조각 문<small>사진: Adam Jones, Ph.D. · CC BY-SA 3.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>잔지바르</th><td>19세기 오만 술탄의 땅, 1890년부터 영국 보호령</td></tr><tr><th>본토</th><td>독일령 동아프리카 (1880년대~1918년)</td></tr><tr><th>1차 대전 뒤</th><td>영국이 맡아 다스린 탕가니카</td></tr><tr><th>저항</th><td>마지마지 봉기 (1905~1907년)</td></tr></table></div></div><div class=\"two\"><div><h3>힘든 시절</h3><p>19세기 해안은 노예 무역의 아픈 역사도 있었어요. 잔지바르 스톤타운에는 그 시절을 기억하는 기념관이 있어요.</p><p>본토는 독일, 뒤에는 영국의 지배를 받았어요.</p></div><div><h3>기억하는 곳</h3><p>바가모요는 옛 무역 길이 끝나는 항구였어요. 옛 건물과 박물관에서 그 시대를 볼 수 있어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">ukoloni</span> <span class=\"r\">우콜로니</span><span class=\"m\">식민지 지배</span></div><div><span class=\"lo\">utumwa</span> <span class=\"r\">우투뫄</span><span class=\"m\">노예 제도</span></div><div><span class=\"lo\">vita</span> <span class=\"r\">비타</span><span class=\"m\">전쟁</span></div><div><span class=\"lo\">Mjerumani</span> <span class=\"r\">음제루마니</span><span class=\"m\">독일 사람</span></div><div><span class=\"lo\">Mwingereza</span> <span class=\"r\">뮝게레자</span><span class=\"m\">영국 사람</span></div></div>"},"8-03-03":{"t":"독립과 하나 됨","h":"Uhuru na Muungano","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>독립과 하나 됨</h2><div class=\"sub2 lo\">Uhuru na Muungano</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/nyerere.jpg\" width=\"800\" height=\"531\" loading=\"lazy\" alt=\"\"><figcaption>도도마의 니에레레 동상<small>사진: Pernille Bærendtsen · CC BY-SA 2.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>탕가니카 독립</th><td>1961년 12월 9일</td></tr><tr><th>초대 대통령</th><td>줄리어스 니에레레 <span class=\"lo\">Mwalimu Nyerere</span> <span class=\"r\">뫌리무 녜레레</span></td></tr><tr><th>잔지바르 혁명</th><td>1964년 1월 12일</td></tr><tr><th>연합</th><td>1964년 4월 26일, 탄자니아 탄생</td></tr><tr><th>구호</th><td><span class=\"lo\">Uhuru na Umoja</span> <span class=\"r\">우후루 나 우모자</span> (자유와 단결)</td></tr></table></div></div><div class=\"two\"><div><h3>선생님이라 불린 대통령</h3><p>니에레레는 교사 출신이라 지금도 <span class=\"lo\">Mwalimu</span> <span class=\"r\">뫌리무</span>(선생님)라고 불려요. 스와힐리어를 나라말로 세우고, 여러 민족이 한 나라 사람이라는 생각을 키웠어요.</p></div><div><h3>평화로운 나라</h3><p>독립 뒤 큰 내전 없이 지내 온 편이라, 이웃 나라의 피난민을 많이 받아들이기도 했어요. 다당제는 1992년에 다시 시작했어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">uhuru</span> <span class=\"r\">우후루</span><span class=\"m\">자유, 독립</span></div><div><span class=\"lo\">umoja</span> <span class=\"r\">우모자</span><span class=\"m\">단결</span></div><div><span class=\"lo\">mapinduzi</span> <span class=\"r\">마핀두지</span><span class=\"m\">혁명</span></div><div><span class=\"lo\">rais</span> <span class=\"r\">라이스</span><span class=\"m\">대통령</span></div><div><span class=\"lo\">taifa</span> <span class=\"r\">타이파</span><span class=\"m\">나라, 민족</span></div></div>"},"8-04-01":{"t":"여러 종교가 함께","h":"Dini mbalimbali","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>여러 종교가 함께</h2><div class=\"sub2 lo\">Dini mbalimbali</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/church.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>다르에스살람의 아자니아 프런트 루터교회<small>사진: David Stanley from Nanaimo, Canada · CC BY 2.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>기독교</th><td>국민의 60% 안팎 (가톨릭, 루터교, 성공회 등)</td></tr><tr><th>이슬람</th><td>국민의 35% 안팎, 해안과 잔지바르에 많음</td></tr><tr><th>잔지바르</th><td>거의 모두 이슬람</td></tr><tr><th>전통 신앙</th><td>조상과 자연을 섬기는 믿음이 함께 남아 있음</td></tr><tr><th>나라</th><td>정해진 국교 없음</td></tr></table></div></div><div class=\"two\"><div><h3>이웃끼리 서로 존중</h3><p>한 가족 안에 기독교인과 무슬림이 함께 있는 경우도 있어요. 크리스마스와 이드(라마단이 끝나는 날) 모두 나라 공휴일이에요.</p></div><div><h3>인사 속의 종교</h3><p>무슬림 지역에서는 <span class=\"lo\">Assalamu alaikum</span> <span class=\"r\">앗살라무 알라이쿰</span>이라고 인사하기도 해요. 대답은 <span class=\"lo\">Waalaikum salaam</span> <span class=\"r\">와알라이쿰 살람</span>이에요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">dini</span> <span class=\"r\">디니</span><span class=\"m\">종교</span></div><div><span class=\"lo\">kanisa</span> <span class=\"r\">카니사</span><span class=\"m\">교회</span></div><div><span class=\"lo\">msikiti</span> <span class=\"r\">음시키티</span><span class=\"m\">모스크</span></div><div><span class=\"lo\">Mungu</span> <span class=\"r\">뭉구</span><span class=\"m\">하나님, 신</span></div><div><span class=\"lo\">sala</span> <span class=\"r\">살라</span><span class=\"m\">기도 (이슬람)</span></div></div>"},"8-04-02":{"t":"교회 생활","h":"Kanisani","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>교회 생활</h2><div class=\"sub2 lo\">Kanisani</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>예배</th><td>일요일 오전, 몇 시간씩 걸리기도 함</td></tr><tr><th>합창</th><td><span class=\"lo\">kwaya</span> <span class=\"r\">콰야</span>, 아주 인기</td></tr><tr><th>헌금</th><td><span class=\"lo\">sadaka</span> <span class=\"r\">사다카</span></td></tr><tr><th>옷차림</th><td>단정한 옷, 여성은 원피스나 치마</td></tr></table></div></div><div class=\"two\"><div><h3>노래하는 예배</h3><p>교회마다 합창단이 있고, 북과 손뼉에 맞춰 춤추며 찬양해요. 합창 대회도 열려요.</p></div><div><h3>인사</h3><p><span class=\"lo\">Bwana asifiwe!</span> <span class=\"r\">브와나 아시피웨!</span>(주님을 찬양해요!)라는 인사를 교인끼리 자주 해요. 대답은 <span class=\"lo\">Amina</span> <span class=\"r\">아미나</span>(아멘)예요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">ibada</span> <span class=\"r\">이바다</span><span class=\"m\">예배</span></div><div><span class=\"lo\">kwaya</span> <span class=\"r\">콰야</span><span class=\"m\">합창단</span></div><div><span class=\"lo\">mchungaji</span> <span class=\"r\">음충가지</span><span class=\"m\">목사</span></div><div><span class=\"lo\">padri</span> <span class=\"r\">파드리</span><span class=\"m\">신부</span></div><div><span class=\"lo\">Biblia</span> <span class=\"r\">비블리아</span><span class=\"m\">성경</span></div></div>"},"8-04-03":{"t":"이슬람 생활","h":"Maisha ya Kiislamu","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>이슬람 생활</h2><div class=\"sub2 lo\">Maisha ya Kiislamu</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/mosque.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>잔지바르 모스크의 첨탑<small>사진: Luganosamwel · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>기도</th><td>하루 다섯 번, 모스크에서 아잔이 울림</td></tr><tr><th>금요일</th><td><span class=\"lo\">Ijumaa</span> <span class=\"r\">이주마아</span>, 낮 단체 기도</td></tr><tr><th>라마단</th><td>해 뜰 때부터 질 때까지 금식</td></tr><tr><th>명절</th><td>이드 알피트르, 이드 알아드하</td></tr><tr><th>옷</th><td>남성 <span class=\"lo\">kanzu</span> <span class=\"r\">칸주</span>, 여성 <span class=\"lo\">buibui</span> <span class=\"r\">부이부이</span></td></tr></table></div></div><div class=\"two\"><div><h3>라마단 때 잔지바르</h3><p>낮에는 식당이 많이 닫고, 해가 지면 가족과 이웃이 모여 함께 먹어요. 여행자도 낮에 길에서 먹고 마시는 건 삼가는 게 예의예요.</p></div><div><h3>옷차림</h3><p>이슬람 지역에서는 어깨와 무릎을 가리는 옷이 좋아요. 모스크 안은 신자가 아니면 들어가지 않는 게 보통이에요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">msikiti</span> <span class=\"r\">음시키티</span><span class=\"m\">모스크</span></div><div><span class=\"lo\">Ramadhani</span> <span class=\"r\">라마다니</span><span class=\"m\">라마단</span></div><div><span class=\"lo\">kufunga</span> <span class=\"r\">쿠풍가</span><span class=\"m\">금식하다</span></div><div><span class=\"lo\">Idd</span> <span class=\"r\">이드</span><span class=\"m\">이드 (명절)</span></div><div><span class=\"lo\">kanzu</span> <span class=\"r\">칸주</span><span class=\"m\">남성의 긴 흰 옷</span></div></div>"},"8-05-01":{"t":"나라 공휴일","h":"Sikukuu za kitaifa","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>나라 공휴일</h2><div class=\"sub2 lo\">Sikukuu za kitaifa</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>1월 12일</th><td>잔지바르 혁명 기념일</td></tr><tr><th>4월 26일</th><td>연합의 날 (탄자니아 탄생)</td></tr><tr><th>7월 7일</th><td><span class=\"lo\">Saba Saba</span> <span class=\"r\">사바 사바</span> (무역 박람회)</td></tr><tr><th>8월 8일</th><td><span class=\"lo\">Nane Nane</span> <span class=\"r\">나네 나네</span> (농민의 날)</td></tr><tr><th>10월 14일</th><td>니에레레의 날</td></tr><tr><th>12월 9일</th><td>독립 기념일</td></tr></table></div></div><div class=\"two\"><div><h3>숫자로 부르는 날</h3><p>7월 7일은 일곱(<span class=\"lo\">saba</span> <span class=\"r\">사바</span>)을 두 번, 8월 8일은 여덟(<span class=\"lo\">nane</span> <span class=\"r\">나네</span>)을 두 번 써서 이름을 지었어요.</p><p>나네나네에는 지역마다 농업 박람회가 열려 농산물과 가축, 새 농기구를 구경해요.</p></div><div><h3>기념일 풍경</h3><p>독립 기념일과 연합의 날에는 경기장에서 행진과 공연이 있고, 텔레비전으로 중계해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">sikukuu</span> <span class=\"r\">시쿠쿠우</span><span class=\"m\">명절, 공휴일</span></div><div><span class=\"lo\">saba</span> <span class=\"r\">사바</span><span class=\"m\">일곱</span></div><div><span class=\"lo\">nane</span> <span class=\"r\">나네</span><span class=\"m\">여덟</span></div><div><span class=\"lo\">maonyesho</span> <span class=\"r\">마오녜쇼</span><span class=\"m\">박람회</span></div><div><span class=\"lo\">mkulima</span> <span class=\"r\">음쿨리마</span><span class=\"m\">농부</span></div></div>"},"8-05-02":{"t":"크리스마스와 새해","h":"Krismasi na Mwaka Mpya","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>크리스마스와 새해</h2><div class=\"sub2 lo\">Krismasi na Mwaka Mpya</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>크리스마스</th><td>12월 25일, 26일도 쉼</td></tr><tr><th>부활절</th><td>성금요일과 부활절 월요일</td></tr><tr><th>새해</th><td>1월 1일</td></tr><tr><th>인사</th><td><span class=\"lo\">Krismasi njema!</span> <span class=\"r\">크리스마시 은제마!</span>, <span class=\"lo\">Heri ya mwaka mpya!</span> <span class=\"r\">헤리 야 뫄카 음퍄!</span></td></tr></table></div></div><div class=\"two\"><div><h3>고향에 가는 때</h3><p>연말이면 도시에 사는 사람들이 고향 마을로 돌아가요. 버스표가 일찍 팔리고 터미널이 붐벼요.</p><p>가족이 모이면 염소나 닭을 잡고 필라우를 지어 잔치를 해요.</p></div><div><h3>인사</h3><p>크리스마스에는 <span class=\"lo\">Krismasi njema</span> <span class=\"r\">크리스마시 은제마</span>, 새해에는 <span class=\"lo\">Heri ya mwaka mpya</span> <span class=\"r\">헤리 야 뫄카 음퍄</span>라고 인사해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">Krismasi</span> <span class=\"r\">크리스마시</span><span class=\"m\">크리스마스</span></div><div><span class=\"lo\">Pasaka</span> <span class=\"r\">파사카</span><span class=\"m\">부활절</span></div><div><span class=\"lo\">mwaka mpya</span> <span class=\"r\">뫄카 음퍄</span><span class=\"m\">새해</span></div><div><span class=\"lo\">nyumbani</span> <span class=\"r\">늄바니</span><span class=\"m\">고향, 집</span></div><div><span class=\"lo\">zawadi</span> <span class=\"r\">자와디</span><span class=\"m\">선물</span></div></div>"},"8-05-03":{"t":"이드와 축제","h":"Idd na tamasha","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>이드와 축제</h2><div class=\"sub2 lo\">Idd na tamasha</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>이드 알피트르</th><td>라마단이 끝나는 날 <span class=\"lo\">Idd el Fitr</span> <span class=\"r\">이드 엘피트르</span></td></tr><tr><th>이드 알아드하</th><td>희생제 <span class=\"lo\">Idd el Hajj</span> <span class=\"r\">이드 엘하즈</span></td></tr><tr><th>마울리드</th><td>예언자 탄생일</td></tr><tr><th>음악 축제</th><td>잔지바르 사우티 자 부사라 (2월)</td></tr><tr><th>영화 축제</th><td>잔지바르 국제 영화제 (7월)</td></tr></table></div></div><div class=\"two\"><div><h3>이드</h3><p>새 옷을 입고 아침 기도를 한 뒤 친척과 이웃을 찾아가요. 아이들은 용돈과 과자를 받아요. 인사는 <span class=\"lo\">Idd mubarak</span> <span class=\"r\">이드 무바라크</span>예요.</p></div><div><h3>음악과 축제</h3><p>잔지바르에서는 타랍, 봉고 플라바, 아프리카 여러 나라 음악가가 모이는 음악 축제가 열려요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">Idd</span> <span class=\"r\">이드</span><span class=\"m\">이드</span></div><div><span class=\"lo\">tamasha</span> <span class=\"r\">타마샤</span><span class=\"m\">축제</span></div><div><span class=\"lo\">muziki</span> <span class=\"r\">무지키</span><span class=\"m\">음악</span></div><div><span class=\"lo\">nguo mpya</span> <span class=\"r\">응구오 음퍄</span><span class=\"m\">새 옷</span></div><div><span class=\"lo\">kusherehekea</span> <span class=\"r\">쿠셰레헤케아</span><span class=\"m\">축하하다</span></div></div>"},"8-05-04":{"t":"결혼과 가족 행사","h":"Harusi","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>결혼과 가족 행사</h2><div class=\"sub2 lo\">Harusi</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>결혼 준비</th><td>신랑 집에서 신부 집에 <span class=\"lo\">mahari</span> <span class=\"r\">마하리</span>(신부 값)를 정함</td></tr><tr><th>신부 잔치</th><td><span class=\"lo\">kitchen party</span> <span class=\"r\">키친 파티</span>, <span class=\"lo\">send-off</span> <span class=\"r\">센드오프</span></td></tr><tr><th>결혼식</th><td>교회·모스크 예식 뒤 큰 잔치</td></tr><tr><th>도움</th><td>친척과 친구가 모임을 열어 돈을 모음 <span class=\"lo\">mchango</span> <span class=\"r\">음창고</span></td></tr></table></div></div><div class=\"two\"><div><h3>모두가 돕는 잔치</h3><p>결혼식 비용은 가족만 내지 않아요. 친구와 동료가 준비 모임에 와서 조금씩 돈을 보태요. 이것을 <span class=\"lo\">mchango</span> <span class=\"r\">음창고</span>라고 해요.</p></div><div><h3>춤과 노래</h3><p>잔치에서는 사회자 <span class=\"lo\">MC</span> <span class=\"r\">엠시</span>가 분위기를 띄우고, 손님들이 줄지어 춤추며 선물을 건네요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">harusi</span> <span class=\"r\">하루시</span><span class=\"m\">결혼식</span></div><div><span class=\"lo\">bibi harusi</span> <span class=\"r\">비비 하루시</span><span class=\"m\">신부</span></div><div><span class=\"lo\">bwana harusi</span> <span class=\"r\">브와나 하루시</span><span class=\"m\">신랑</span></div><div><span class=\"lo\">mahari</span> <span class=\"r\">마하리</span><span class=\"m\">신부 값</span></div><div><span class=\"lo\">mchango</span> <span class=\"r\">음창고</span><span class=\"m\">보태는 돈</span></div></div>"},"8-06-01":{"t":"주식","h":"Vyakula vikuu","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>주식</h2><div class=\"sub2 lo\">Vyakula vikuu</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/ugali.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>우갈리와 반찬<small>사진: MWANI · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>우갈리</th><td><span class=\"lo\">ugali</span> <span class=\"r\">우갈리</span> (옥수수 가루를 쑨 떡)</td></tr><tr><th>밥</th><td><span class=\"lo\">wali</span> <span class=\"r\">왈리</span> (해안은 코코넛 밥 <span class=\"lo\">wali wa nazi</span> <span class=\"r\">왈리 와 나지</span>)</td></tr><tr><th>필라우</th><td><span class=\"lo\">pilau</span> <span class=\"r\">필라우</span> (향신료 볶음밥)</td></tr><tr><th>바나나</th><td><span class=\"lo\">ndizi</span> <span class=\"r\">은디지</span>, 북서부는 <span class=\"lo\">matoke</span> <span class=\"r\">마토케</span></td></tr><tr><th>빵</th><td><span class=\"lo\">chapati</span> <span class=\"r\">차파티</span>, <span class=\"lo\">maandazi</span> <span class=\"r\">마안다지</span></td></tr></table></div></div><div class=\"two\"><div><h3>우갈리</h3><p>가장 흔한 주식이에요. 손으로 조금 떼어 동그랗게 만든 뒤 국물이나 반찬에 찍어 먹어요. 오른손으로 먹어요.</p></div><div><h3>반찬</h3><p>콩 <span class=\"lo\">maharage</span> <span class=\"r\">마하라게</span>, 고기 국물 <span class=\"lo\">mchuzi</span> <span class=\"r\">음추지</span>, 푸른 잎 채소 <span class=\"lo\">mboga za majani</span> <span class=\"r\">음보가 자 마자니</span>와 함께 먹어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">ugali</span> <span class=\"r\">우갈리</span><span class=\"m\">우갈리</span></div><div><span class=\"lo\">wali</span> <span class=\"r\">왈리</span><span class=\"m\">밥</span></div><div><span class=\"lo\">maharage</span> <span class=\"r\">마하라게</span><span class=\"m\">콩</span></div><div><span class=\"lo\">mchuzi</span> <span class=\"r\">음추지</span><span class=\"m\">국물 요리</span></div><div><span class=\"lo\">mboga</span> <span class=\"r\">음보가</span><span class=\"m\">채소, 반찬</span></div></div>"},"8-06-02":{"t":"길거리 음식","h":"Vyakula vya mtaani","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>길거리 음식</h2><div class=\"sub2 lo\">Vyakula vya mtaani</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/mishkaki.jpg\" width=\"800\" height=\"588\" loading=\"lazy\" alt=\"\"><figcaption>코코 해변의 미시카키와 감자튀김<small>사진: Zizounyc · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>칩시 마야이</th><td><span class=\"lo\">chipsi mayai</span> <span class=\"r\">칩시 마야이</span> (감자튀김 오믈렛)</td></tr><tr><th>미시카키</th><td><span class=\"lo\">mishkaki</span> <span class=\"r\">미시카키</span> (소고기 꼬치)</td></tr><tr><th>냐마 초마</th><td><span class=\"lo\">nyama choma</span> <span class=\"r\">냐마 초마</span> (숯불 고기)</td></tr><tr><th>잔지바르 피자</th><td>밤 시장의 납작 부침</td></tr><tr><th>우로조</th><td><span class=\"lo\">urojo</span> <span class=\"r\">우로조</span> (잔지바르 수프)</td></tr></table></div></div><div class=\"two\"><div><h3>저녁의 숯불</h3><p>해가 지면 길가에 숯불이 피어올라요. 꼬치와 구운 옥수수 <span class=\"lo\">mahindi ya kuchoma</span> <span class=\"r\">마힌디 야 쿠초마</span>를 사 먹어요.</p></div><div><h3>포로다니 밤 시장</h3><p>잔지바르 스톤타운 바닷가에는 해산물 꼬치, 잔지바르 피자, 사탕수수 주스를 파는 밤 시장이 열려요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">kuchoma</span> <span class=\"r\">쿠초마</span><span class=\"m\">굽다</span></div><div><span class=\"lo\">nyama</span> <span class=\"r\">냐마</span><span class=\"m\">고기</span></div><div><span class=\"lo\">mayai</span> <span class=\"r\">마야이</span><span class=\"m\">달걀</span></div><div><span class=\"lo\">mahindi</span> <span class=\"r\">마힌디</span><span class=\"m\">옥수수</span></div><div><span class=\"lo\">miwa</span> <span class=\"r\">미와</span><span class=\"m\">사탕수수</span></div></div>"},"8-06-03":{"t":"차와 커피, 향신료","h":"Chai, kahawa na viungo","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>차와 커피, 향신료</h2><div class=\"sub2 lo\">Chai, kahawa na viungo</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>차</th><td><span class=\"lo\">chai</span> <span class=\"r\">차이</span>, 우유와 생강을 넣어 끓임</td></tr><tr><th>커피</th><td>킬리만자로와 음베야의 커피</td></tr><tr><th>향신료 섬</th><td>잔지바르: 정향, 계피, 육두구, 후추</td></tr><tr><th>간식</th><td><span class=\"lo\">maandazi</span> <span class=\"r\">마안다지</span>, 땅콩, 코코넛</td></tr></table></div></div><div class=\"two\"><div><h3>아침은 차 한잔</h3><p>아침에 달고 진한 밀크티와 만다지를 먹는 집이 많아요. 차에는 생강 <span class=\"lo\">tangawizi</span> <span class=\"r\">탕가위지</span>이나 카다멈 <span class=\"lo\">iliki</span> <span class=\"r\">일리키</span>을 넣어요.</p></div><div><h3>향신료 투어</h3><p>잔지바르는 정향으로 유명해서 향신료 섬이라 불려요. 농장에 가면 나무에 달린 향신료를 직접 볼 수 있어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">chai</span> <span class=\"r\">차이</span><span class=\"m\">차</span></div><div><span class=\"lo\">kahawa</span> <span class=\"r\">카하와</span><span class=\"m\">커피</span></div><div><span class=\"lo\">viungo</span> <span class=\"r\">비웅고</span><span class=\"m\">양념, 향신료</span></div><div><span class=\"lo\">karafuu</span> <span class=\"r\">카라푸우</span><span class=\"m\">정향</span></div><div><span class=\"lo\">tangawizi</span> <span class=\"r\">탕가위지</span><span class=\"m\">생강</span></div></div>"},"8-06-04":{"t":"식사 예절","h":"Adabu za chakula","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>식사 예절</h2><div class=\"sub2 lo\">Adabu za chakula</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/meal.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>필라우, 꼬치, 바나나 튀김<small>사진: Tcg1111 · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>손 씻기</th><td>먹기 전에 주인이 물과 그릇을 가져와 손을 씻게 해 줌</td></tr><tr><th>손</th><td>오른손으로 먹고 건넴</td></tr><tr><th>인사</th><td>먹기 전 <span class=\"lo\">Karibu chakula</span> <span class=\"r\">카리부 차쿨라</span> (함께 드세요)</td></tr><tr><th>다 먹으면</th><td><span class=\"lo\">Nimeshiba</span> <span class=\"r\">니메쉬바</span> (배불러요), <span class=\"lo\">Asante kwa chakula</span> <span class=\"r\">아산테 콰 차쿨라</span></td></tr></table></div></div><div class=\"two\"><div><h3>함께 드세요</h3><p>식사 때 누가 오면 <span class=\"lo\">Karibu chakula!</span> <span class=\"r\">카리부 차쿨라!</span>이라고 함께 먹자고 권해요. 배가 불러도 조금 맛보는 게 예의예요.</p></div><div><h3>손님 대접</h3><p>손님에게는 가장 좋은 음식을 먼저 줘요. 남기지 않고 맛있게 먹으면 주인이 기뻐해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">kunawa</span> <span class=\"r\">쿠나와</span><span class=\"m\">손을 씻다</span></div><div><span class=\"lo\">mkono wa kulia</span> <span class=\"r\">음코노 와 쿨리아</span><span class=\"m\">오른손</span></div><div><span class=\"lo\">karibu chakula</span> <span class=\"r\">카리부 차쿨라</span><span class=\"m\">함께 드세요</span></div><div><span class=\"lo\">nimeshiba</span> <span class=\"r\">니메쉬바</span><span class=\"m\">배불러요</span></div><div><span class=\"lo\">mgeni</span> <span class=\"r\">음게니</span><span class=\"m\">손님</span></div></div>"},"8-07-01":{"t":"인사가 먼저","h":"Salamu kwanza","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>인사가 먼저</h2><div class=\"sub2 lo\">Salamu kwanza</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>어른께</th><td><span class=\"lo\">Shikamoo</span> <span class=\"r\">쉬카모오</span> → 대답 <span class=\"lo\">Marahaba</span> <span class=\"r\">마라하바</span></td></tr><tr><th>또래끼리</th><td><span class=\"lo\">Mambo?</span> <span class=\"r\">맘보?</span> → <span class=\"lo\">Poa!</span> <span class=\"r\">포아!</span></td></tr><tr><th>보통</th><td><span class=\"lo\">Habari?</span> <span class=\"r\">하바리?</span> → <span class=\"lo\">Nzuri</span> <span class=\"r\">은주리</span></td></tr><tr><th>악수</th><td>오른손, 왼손으로 오른팔을 받치면 더 공손함</td></tr></table></div></div><div class=\"two\"><div><h3>인사는 길게</h3><p>바로 용건을 말하지 않고, 먼저 안부와 가족, 일을 차례로 물어요. 인사를 건너뛰면 무례하게 느낄 수 있어요.</p></div><div><h3>어른 공경</h3><p>아이와 젊은 사람은 어른에게 먼저 <span class=\"lo\">Shikamoo</span> <span class=\"r\">쉬카모오</span>라고 인사해요. \"발을 붙잡는다\"는 옛말에서 왔어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">salamu</span> <span class=\"r\">살라무</span><span class=\"m\">인사</span></div><div><span class=\"lo\">shikamoo</span> <span class=\"r\">쉬카모오</span><span class=\"m\">(어른께) 안녕하세요</span></div><div><span class=\"lo\">marahaba</span> <span class=\"r\">마라하바</span><span class=\"m\">그래 (대답)</span></div><div><span class=\"lo\">mzee</span> <span class=\"r\">음제에</span><span class=\"m\">어르신</span></div><div><span class=\"lo\">heshima</span> <span class=\"r\">헤쉬마</span><span class=\"m\">존경, 예의</span></div></div>"},"8-07-02":{"t":"천천히, 천천히","h":"Pole pole","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>천천히, 천천히</h2><div class=\"sub2 lo\">Pole pole</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/street.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>다르에스살람 카리아쿠 거리<small>사진: Ismizotz · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>말버릇</th><td><span class=\"lo\">Pole pole</span> <span class=\"r\">폴레 폴레</span> (천천히)</td></tr><tr><th>걱정 마요</th><td><span class=\"lo\">Hakuna matata</span> <span class=\"r\">하쿠나 마타타</span></td></tr><tr><th>시간</th><td>약속 시간보다 조금 늦는 일이 흔함</td></tr><tr><th>스와힐리 시간</th><td>아침 7시를 1시로 셈</td></tr></table></div></div><div class=\"two\"><div><h3>폴레 폴레</h3><p>서두르지 않고 천천히 하는 생활 태도를 말해요. 킬리만자로 등반 가이드도 <span class=\"lo\">Pole pole!</span> <span class=\"r\">폴레 폴레!</span>이라며 천천히 오르라고 해요.</p></div><div><h3>시간 읽기</h3><p>스와힐리식 시간은 해 뜨는 아침 7시를 1시로 세요. 약속할 때는 <span class=\"lo\">saa za Kizungu</span> <span class=\"r\">사아 자 키중구</span>(서양식 시간)인지 확인하면 좋아요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">polepole</span> <span class=\"r\">폴레폴레</span><span class=\"m\">천천히</span></div><div><span class=\"lo\">haraka</span> <span class=\"r\">하라카</span><span class=\"m\">서두름</span></div><div><span class=\"lo\">saa</span> <span class=\"r\">사아</span><span class=\"m\">시간, ~시</span></div><div><span class=\"lo\">mapema</span> <span class=\"r\">마페마</span><span class=\"m\">일찍</span></div><div><span class=\"lo\">kuchelewa</span> <span class=\"r\">쿠첼레와</span><span class=\"m\">늦다</span></div></div>"},"8-07-03":{"t":"교통과 생활","h":"Usafiri na maisha","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>교통과 생활</h2><div class=\"sub2 lo\">Usafiri na maisha</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/daladala.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>시장 앞의 보다보다 (오토바이 택시)<small>사진: Yeluma Ntali · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>미니버스</th><td><span class=\"lo\">daladala</span> <span class=\"r\">달라달라</span></td></tr><tr><th>오토바이 택시</th><td><span class=\"lo\">bodaboda</span> <span class=\"r\">보다보다</span></td></tr><tr><th>삼륜차</th><td><span class=\"lo\">bajaji</span> <span class=\"r\">바자지</span></td></tr><tr><th>급행 버스</th><td>다르에스살람 BRT <span class=\"lo\">mwendokasi</span> <span class=\"r\">뭰도카시</span></td></tr><tr><th>기차</th><td>새 표준궤 철도 SGR (다르~도도마)</td></tr></table></div></div><div class=\"two\"><div><h3>달라달라</h3><p>정해진 길을 다니는 미니버스예요. 차장 <span class=\"lo\">konda</span> <span class=\"r\">콘다</span>가 행선지를 외치고 요금을 받아요. 내릴 곳에서 <span class=\"lo\">Shusha!</span> <span class=\"r\">슈샤!</span>(내려 주세요)라고 말해요.</p></div><div><h3>조심할 것</h3><p>보다보다는 빠르지만 위험할 수 있어요. 헬멧을 쓰고 값을 미리 정해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">daladala</span> <span class=\"r\">달라달라</span><span class=\"m\">미니버스</span></div><div><span class=\"lo\">konda</span> <span class=\"r\">콘다</span><span class=\"m\">차장</span></div><div><span class=\"lo\">nauli</span> <span class=\"r\">나울리</span><span class=\"m\">차비</span></div><div><span class=\"lo\">kituo</span> <span class=\"r\">키투오</span><span class=\"m\">정류장</span></div><div><span class=\"lo\">foleni</span> <span class=\"r\">폴레니</span><span class=\"m\">차 막힘, 줄</span></div></div>"},"8-07-04":{"t":"예의와 금기","h":"Adabu na miiko","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>예의와 금기</h2><div class=\"sub2 lo\">Adabu na miiko</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>왼손</th><td>물건을 주고받을 때 쓰지 않음</td></tr><tr><th>사진</th><td>사람을 찍기 전에 꼭 물어봄</td></tr><tr><th>옷</th><td>도시 밖과 잔지바르에서는 단정한 옷</td></tr><tr><th>흥정</th><td>시장에서는 웃으며 깎는 것이 보통</td></tr><tr><th>애정 표현</th><td>사람 많은 곳에서는 삼감</td></tr></table></div></div><div class=\"two\"><div><h3>물어보고 찍기</h3><p>특히 마사이 사람들이나 시장 상인을 찍을 때는 <span class=\"lo\">Naweza kupiga picha?</span> <span class=\"r\">나웨자 쿠피가 피차?</span>라고 먼저 물어요. 돈을 요구하는 경우도 있어요.</p></div><div><h3>흥정</h3><p>시장에서는 값을 깎는 게 자연스러워요. <span class=\"lo\">Punguza kidogo</span> <span class=\"r\">풍구자 키도고</span>(좀 깎아 주세요)라고 웃으며 말해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">adabu</span> <span class=\"r\">아다부</span><span class=\"m\">예의</span></div><div><span class=\"lo\">mwiko</span> <span class=\"r\">뮈코</span><span class=\"m\">금기</span></div><div><span class=\"lo\">ruhusa</span> <span class=\"r\">루후사</span><span class=\"m\">허락</span></div><div><span class=\"lo\">kupunguza</span> <span class=\"r\">쿠풍구자</span><span class=\"m\">깎다</span></div><div><span class=\"lo\">heshima</span> <span class=\"r\">헤쉬마</span><span class=\"m\">예의, 존중</span></div></div>"},"8-08-01":{"t":"음악","h":"Muziki","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>음악</h2><div class=\"sub2 lo\">Muziki</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/music.jpg\" width=\"800\" height=\"533\" loading=\"lazy\" alt=\"\"><figcaption>잔지바르 타랍 공연<small>사진: Imani selemani Nsamila · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>봉고 플라바</th><td><span class=\"lo\">Bongo Flava</span> <span class=\"r\">봉고 플라바</span>, 요즘 가장 인기</td></tr><tr><th>타랍</th><td><span class=\"lo\">taarab</span> <span class=\"r\">타아랍</span>, 잔지바르의 노래</td></tr><tr><th>싱게리</th><td><span class=\"lo\">singeli</span> <span class=\"r\">싱겔리</span>, 빠른 거리 음악</td></tr><tr><th>전통 음악</th><td><span class=\"lo\">ngoma</span> <span class=\"r\">응고마</span> (북과 춤)</td></tr><tr><th>유명 가수</th><td>다이아몬드 플래티넘즈 등</td></tr></table></div></div><div class=\"two\"><div><h3>봉고 플라바</h3><p>힙합, 레게, 아프리카 리듬을 섞은 탄자니아 대중음악이에요. 스와힐리어 가사라 동아프리카 전체에서 들어요.</p></div><div><h3>타랍</h3><p>아랍, 인도, 아프리카 음악이 만난 잔지바르 노래예요. 바이올린과 우드, 북이 함께 연주해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">muziki</span> <span class=\"r\">무지키</span><span class=\"m\">음악</span></div><div><span class=\"lo\">wimbo</span> <span class=\"r\">윔보</span><span class=\"m\">노래</span></div><div><span class=\"lo\">mwimbaji</span> <span class=\"r\">뮘바지</span><span class=\"m\">가수</span></div><div><span class=\"lo\">ngoma</span> <span class=\"r\">응고마</span><span class=\"m\">북, 전통 춤</span></div><div><span class=\"lo\">kucheza</span> <span class=\"r\">쿠체자</span><span class=\"m\">춤추다</span></div></div>"},"8-08-02":{"t":"그림과 조각","h":"Sanaa","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>그림과 조각</h2><div class=\"sub2 lo\">Sanaa</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/tinga.jpg\" width=\"800\" height=\"611\" loading=\"lazy\" alt=\"\"><figcaption>팅가팅가 그림 (얼룩말)<small>사진: Ingo Koll (scan) - Rubuni Rashid Said (artist) · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>팅가팅가</th><td><span class=\"lo\">Tingatinga</span> <span class=\"r\">팅가팅가</span> (밝은 색의 동물 그림)</td></tr><tr><th>마콘데 조각</th><td><span class=\"lo\">Makonde</span> <span class=\"r\">마콘데</span> 사람들의 흑단 조각</td></tr><tr><th>천</th><td><span class=\"lo\">kanga</span> <span class=\"r\">캉가</span>, <span class=\"lo\">kitenge</span> <span class=\"r\">키텡게</span></td></tr><tr><th>바구니</th><td>야자잎으로 엮은 바구니와 돗자리</td></tr></table></div></div><div class=\"two\"><div><h3>팅가팅가</h3><p>1960년대에 다르에스살람의 화가 팅가팅가가 시작한 그림이에요. 에나멜 물감으로 동물과 새를 밝고 단순하게 그려요.</p></div><div><h3>캉가</h3><p>캉가는 두 장이 한 벌인 무늬 천이에요. 가운데 스와힐리어 속담이나 짧은 글이 적혀 있어서, 천으로 마음을 전하기도 해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">sanaa</span> <span class=\"r\">사나아</span><span class=\"m\">예술</span></div><div><span class=\"lo\">mchoro</span> <span class=\"r\">음초로</span><span class=\"m\">그림</span></div><div><span class=\"lo\">kinyago</span> <span class=\"r\">키냐고</span><span class=\"m\">조각, 가면</span></div><div><span class=\"lo\">kanga</span> <span class=\"r\">캉가</span><span class=\"m\">캉가 (글귀가 있는 천)</span></div><div><span class=\"lo\">kitenge</span> <span class=\"r\">키텡게</span><span class=\"m\">키텡게 (무늬 천)</span></div></div>"},"8-08-03":{"t":"말과 이야기","h":"Lugha na fasihi","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>말과 이야기</h2><div class=\"sub2 lo\">Lugha na fasihi</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>글말</th><td>라틴 문자 (옛날에는 아랍 문자)</td></tr><tr><th>유명 작가</th><td>샤반 로버트 (스와힐리 문학의 아버지)</td></tr><tr><th>속담</th><td><span class=\"lo\">methali</span> <span class=\"r\">메살리</span>, 일상에서 자주 씀</td></tr><tr><th>수수께끼</th><td><span class=\"lo\">kitendawili</span> <span class=\"r\">키텐다윌리</span> → 대답 <span class=\"lo\">tega</span> <span class=\"r\">테가</span></td></tr></table></div></div><div class=\"two\"><div><h3>속담</h3><p><span class=\"lo\">Haraka haraka haina baraka</span> <span class=\"r\">하라카 하라카 하이나 바라카</span> (서두르면 복이 없다), <span class=\"lo\">Pole pole ndio mwendo</span> <span class=\"r\">폴레 폴레 은디오 뭰도</span> (천천히 가는 게 제대로 가는 것)처럼 속담을 대화에 자주 섞어요.</p></div><div><h3>수수께끼 놀이</h3><p>한 사람이 <span class=\"lo\">Kitendawili!</span> <span class=\"r\">키텐다윌리!</span>이라고 하면 다른 사람들이 <span class=\"lo\">Tega!</span> <span class=\"r\">테가!</span>(내 봐!)라고 대답하고 놀이가 시작돼요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">methali</span> <span class=\"r\">메살리</span><span class=\"m\">속담</span></div><div><span class=\"lo\">hadithi</span> <span class=\"r\">하디시</span><span class=\"m\">이야기</span></div><div><span class=\"lo\">kitendawili</span> <span class=\"r\">키텐다윌리</span><span class=\"m\">수수께끼</span></div><div><span class=\"lo\">shairi</span> <span class=\"r\">샤이리</span><span class=\"m\">시</span></div><div><span class=\"lo\">mwandishi</span> <span class=\"r\">뫈디쉬</span><span class=\"m\">작가</span></div></div>"},"8-08-04":{"t":"운동","h":"Michezo","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>운동</h2><div class=\"sub2 lo\">Michezo</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>가장 인기</th><td>축구 <span class=\"lo\">mpira wa miguu</span> <span class=\"r\">음피라 와 미구우</span></td></tr><tr><th>라이벌</th><td><span class=\"lo\">Simba</span> <span class=\"r\">심바</span> 대 <span class=\"lo\">Yanga</span> <span class=\"r\">양가</span> (다르에스살람)</td></tr><tr><th>달리기</th><td>장거리 달리기 선수가 많음</td></tr><tr><th>킬리만자로 마라톤</th><td>모시에서 해마다 열림</td></tr></table></div></div><div class=\"two\"><div><h3>심바와 양가</h3><p>두 팀의 경기 <span class=\"lo\">Dabi ya Kariakoo</span> <span class=\"r\">다비 야 카리아코오</span>(카리아쿠 더비)가 열리면 온 나라가 들썩여요. 친구끼리도 응원하는 팀이 달라 농담을 주고받아요.</p></div><div><h3>동네 축구</h3><p>저녁이면 공터에서 아이들이 공을 차요. 공은 비닐을 뭉쳐 끈으로 묶어 만들기도 해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mpira</span> <span class=\"r\">음피라</span><span class=\"m\">공, 축구</span></div><div><span class=\"lo\">mchezaji</span> <span class=\"r\">음체자지</span><span class=\"m\">선수</span></div><div><span class=\"lo\">timu</span> <span class=\"r\">티무</span><span class=\"m\">팀</span></div><div><span class=\"lo\">goli</span> <span class=\"r\">골리</span><span class=\"m\">골</span></div><div><span class=\"lo\">kushinda</span> <span class=\"r\">쿠쉰다</span><span class=\"m\">이기다</span></div></div>"},"8-09-01":{"t":"킬리만자로","h":"Mlima Kilimanjaro","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>킬리만자로</h2><div class=\"sub2 lo\">Mlima Kilimanjaro</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>높이</th><td>5,895m (우후루 봉)</td></tr><tr><th>가는 길</th><td>모시나 아루샤에서 출발</td></tr><tr><th>오르기</th><td>보통 6~8일, 여러 등산로</td></tr><tr><th>세계유산</th><td>킬리만자로 국립공원 (1987년)</td></tr><tr><th>좋은 때</th><td>1~3월, 6~10월 (건기)</td></tr></table></div></div><div class=\"two\"><div><h3>걸어서 오르는 최고봉</h3><p>전문 장비 없이 걸어서 오를 수 있는 가장 높은 산 가운데 하나예요. 가이드와 짐꾼이 함께 가야 해요.</p><p>고산병을 막으려면 천천히, <span class=\"lo\">Pole pole</span> <span class=\"r\">폴레 폴레</span>!</p></div><div><h3>산기슭</h3><p>모시 근처 마을에서는 차가족 사람들이 커피와 바나나를 길러요. 커피 농장 투어도 할 수 있어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mlima</span> <span class=\"r\">음리마</span><span class=\"m\">산</span></div><div><span class=\"lo\">kilele</span> <span class=\"r\">킬렐레</span><span class=\"m\">봉우리</span></div><div><span class=\"lo\">kupanda</span> <span class=\"r\">쿠판다</span><span class=\"m\">오르다</span></div><div><span class=\"lo\">mpagazi</span> <span class=\"r\">음파가지</span><span class=\"m\">짐꾼</span></div><div><span class=\"lo\">theluji</span> <span class=\"r\">셀루지</span><span class=\"m\">눈</span></div></div>"},"8-09-02":{"t":"세렝게티와 응고롱고로","h":"Serengeti na Ngorongoro","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>세렝게티와 응고롱고로</h2><div class=\"sub2 lo\">Serengeti na Ngorongoro</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>세렝게티</th><td>끝없는 초원, 누 떼의 대이동</td></tr><tr><th>응고롱고로</th><td>거대한 분화구 안의 동물 세계</td></tr><tr><th>세계유산</th><td>둘 다 유네스코 세계유산</td></tr><tr><th>출발 도시</th><td>아루샤</td></tr><tr><th>함께 가는 곳</th><td>타랑기레, 마냐라 호수</td></tr></table></div></div><div class=\"two\"><div><h3>끝없는 초원</h3><p>세렝게티라는 이름은 마사이 말로 \"끝없는 땅\"이라는 뜻이에요. 사자, 표범, 치타를 볼 수 있어요.</p></div><div><h3>분화구</h3><p>응고롱고로는 옛 화산이 무너져 생긴 큰 분지예요. 그 안에서 동물들이 살고, 마사이 사람들은 가축을 데리고 주변에 살아요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mbuga</span> <span class=\"r\">음부가</span><span class=\"m\">초원, 국립공원</span></div><div><span class=\"lo\">safari</span> <span class=\"r\">사파리</span><span class=\"m\">여행, 사파리</span></div><div><span class=\"lo\">kiongozi</span> <span class=\"r\">키옹고지</span><span class=\"m\">가이드</span></div><div><span class=\"lo\">chui</span> <span class=\"r\">추이</span><span class=\"m\">표범</span></div><div><span class=\"lo\">nyumbu</span> <span class=\"r\">늄부</span><span class=\"m\">누</span></div></div>"},"8-09-03":{"t":"잔지바르","h":"Zanzibar","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>잔지바르</h2><div class=\"sub2 lo\">Zanzibar</div><div class=\"top1\"><div><table class=\"facts\"><tr><th>스톤타운</th><td><span class=\"lo\">Mji Mkongwe</span> <span class=\"r\">음지 음콩궤</span>, 세계유산 (2000년)</td></tr><tr><th>볼 것</th><td>조각 문, 옛 요새, 경이의 집, 시장</td></tr><tr><th>바다</th><td>능위, 파제 해변</td></tr><tr><th>즐기기</th><td>향신료 투어, 다우 돛배, 스노클링</td></tr><tr><th>가는 길</th><td>다르에스살람에서 배 2시간쯤 또는 비행기</td></tr></table></div></div><div class=\"two\"><div><h3>스톤타운</h3><p>좁은 골목이 미로처럼 이어지고, 무늬를 새긴 나무 문이 많아요. 길을 잃는 것도 여행의 재미예요.</p></div><div><h3>해변</h3><p>하얀 모래와 맑은 바다로 유명해요. 썰물과 밀물 차이가 커서 해변 모습이 하루에도 크게 바뀌어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">mji mkongwe</span> <span class=\"r\">음지 음콩궤</span><span class=\"m\">구시가지</span></div><div><span class=\"lo\">mlango</span> <span class=\"r\">음랑고</span><span class=\"m\">문</span></div><div><span class=\"lo\">ufukwe</span> <span class=\"r\">우푸퀘</span><span class=\"m\">해변</span></div><div><span class=\"lo\">jahazi</span> <span class=\"r\">자하지</span><span class=\"m\">다우 돛배</span></div><div><span class=\"lo\">viungo</span> <span class=\"r\">비웅고</span><span class=\"m\">향신료</span></div></div>"},"8-09-04":{"t":"다르에스살람","h":"Dar es Salaam","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>다르에스살람</h2><div class=\"sub2 lo\">Dar es Salaam</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/dar.jpg\" width=\"800\" height=\"600\" loading=\"lazy\" alt=\"\"><figcaption>다르에스살람 항구를 떠나는 배<small>사진: FredyVC · CC BY-SA 4.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>이름 뜻</th><td>아랍어로 \"평화의 집\"</td></tr><tr><th>볼 것</th><td>카리아쿠 시장, 국립 박물관, 어시장</td></tr><tr><th>바다</th><td>코코 해변, 가까운 섬 봉고요</td></tr><tr><th>교통</th><td>급행 버스 BRT, 페리</td></tr><tr><th>공항</th><td>줄리어스 니에레레 국제공항</td></tr></table></div></div><div class=\"two\"><div><h3>바쁜 항구 도시</h3><p>탄자니아의 경제 중심이에요. 카리아쿠 시장에는 옷, 전자제품, 식료품까지 없는 게 없어요.</p></div><div><h3>어시장</h3><p>항구 옆 어시장에서는 아침마다 경매가 열리고, 고른 생선을 바로 튀겨 주기도 해요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">bandari</span> <span class=\"r\">반다리</span><span class=\"m\">항구</span></div><div><span class=\"lo\">soko</span> <span class=\"r\">소코</span><span class=\"m\">시장</span></div><div><span class=\"lo\">samaki</span> <span class=\"r\">사마키</span><span class=\"m\">생선</span></div><div><span class=\"lo\">feri</span> <span class=\"r\">페리</span><span class=\"m\">페리</span></div><div><span class=\"lo\">makumbusho</span> <span class=\"r\">마쿰부쇼</span><span class=\"m\">박물관</span></div></div>"},"8-09-05":{"t":"호수와 남쪽","h":"Maziwa na kusini","i":"","w":[],"tp":[],"nx":[],"pr":[],"dl":[],"sm":null,"qz":[],"info":"<h2>호수와 남쪽</h2><div class=\"sub2 lo\">Maziwa na kusini</div><div class=\"top2\"><div><figure class=\"ph\"><img src=\"img/tz/victoria.jpg\" width=\"800\" height=\"524\" loading=\"lazy\" alt=\"\"><figcaption>므완자의 빅토리아 호숫가<small>사진: Jonathan Stonehouse · CC BY 2.0 · Wikimedia Commons</small></figcaption></figure></div><div><table class=\"facts\"><tr><th>므완자</th><td>빅토리아 호숫가 도시, 바위섬이 많음</td></tr><tr><th>키고마</th><td>탕가니카 호숫가, 침팬지 국립공원 곰베</td></tr><tr><th>남부 고원</th><td>이링가, 음베야, 차밭이 많은 서늘한 땅</td></tr><tr><th>남부 공원</th><td>루아하, 니에레레 국립공원</td></tr><tr><th>바가모요</th><td>옛 항구 도시와 예술 학교</td></tr></table></div></div><div class=\"two\"><div><h3>침팬지를 만나는 곳</h3><p>곰베 국립공원은 제인 구달이 침팬지를 연구한 곳이에요. 배를 타고 들어가요.</p></div><div><h3>조용한 남쪽</h3><p>남쪽은 북쪽보다 여행자가 적어 한적해요. 루아하 공원은 코끼리가 많고, 이링가 근처는 차밭이 넓어요.</p></div></div><h3>알아 둘 말</h3><div class=\"terms\"><div><span class=\"lo\">ziwa</span> <span class=\"r\">지와</span><span class=\"m\">호수</span></div><div><span class=\"lo\">kisiwa</span> <span class=\"r\">키시와</span><span class=\"m\">섬</span></div><div><span class=\"lo\">sokwe</span> <span class=\"r\">소퀘</span><span class=\"m\">침팬지</span></div><div><span class=\"lo\">chai</span> <span class=\"r\">차이</span><span class=\"m\">차 (차밭)</span></div><div><span class=\"lo\">mvuvi</span> <span class=\"r\">음부비</span><span class=\"m\">어부</span></div></div>"}},"blab":{"8-01-01":["나라 이름과 국기","Jina la nchi na bendera"],"8-01-02":["수도와 인구","Mji mkuu na wakazi"],"8-01-03":["정부와 행정","Serikali"],"8-01-04":["말과 돈","Lugha na fedha"],"8-02-01":["산과 호수","Milima na maziwa"],"8-02-02":["날씨와 계절","Hali ya hewa"],"8-02-03":["본토와 섬","Bara na Visiwani"],"8-02-04":["동물과 자연","Wanyamapori"],"8-03-01":["스와힐리 해안의 옛날","Historia ya pwani"],"8-03-02":["식민지 시대","Ukoloni"],"8-03-03":["독립과 하나 됨","Uhuru na Muungano"],"8-04-01":["여러 종교가 함께","Dini mbalimbali"],"8-04-02":["교회 생활","Kanisani"],"8-04-03":["이슬람 생활","Maisha ya Kiislamu"],"8-05-01":["나라 공휴일","Sikukuu za kitaifa"],"8-05-02":["크리스마스와 새해","Krismasi na Mwaka Mpya"],"8-05-03":["이드와 축제","Idd na tamasha"],"8-05-04":["결혼과 가족 행사","Harusi"],"8-06-01":["주식","Vyakula vikuu"],"8-06-02":["길거리 음식","Vyakula vya mtaani"],"8-06-03":["차와 커피, 향신료","Chai, kahawa na viungo"],"8-06-04":["식사 예절","Adabu za chakula"],"8-07-01":["인사가 먼저","Salamu kwanza"],"8-07-02":["천천히, 천천히","Pole pole"],"8-07-03":["교통과 생활","Usafiri na maisha"],"8-07-04":["예의와 금기","Adabu na miiko"],"8-08-01":["음악","Muziki"],"8-08-02":["그림과 조각","Sanaa"],"8-08-03":["말과 이야기","Lugha na fasihi"],"8-08-04":["운동","Michezo"],"8-09-01":["킬리만자로","Mlima Kilimanjaro"],"8-09-02":["세렝게티와 응고롱고로","Serengeti na Ngorongoro"],"8-09-03":["잔지바르","Zanzibar"],"8-09-04":["다르에스살람","Dar es Salaam"],"8-09-05":["호수와 남쪽","Maziwa na kusini"]}};DATA.P.push(TZINFO.part);Object.assign(DATA.B,TZINFO.B);
